const msg = $json.message;
const text = (msg && msg.text || '').trim();
const parts = text.split(/\s+/);
const command = (parts[0] || '').toLowerCase();
const content = parts.slice(1).join(' ').trim();
const from = msg.from || {};

return {
  json: {
    command,
    // idea_text: kept exactly as-is so the existing /idea branch is untouched.
    idea_text: content,
    // content_text: generic alias of the same value, used by the other five
    // command branches (question/suggestion/decision/action/observation) so
    // they don't each need their own copy of this parsing logic.
    content_text: content,
    // Display-only attribution (matches 07_DATABASE_SCHEMA.md's MVP scope note:
    // Telegram participants are identified by raw username/first name, not a
    // persistent account ID - no account linking exists in the MVP).
    telegram_display_name: from.username || from.first_name || 'unknown',
    // Used only to authorize Save/Cancel callbacks. It is NOT written
    // to the permanent knowledge tables.
    telegram_user_id: from.id != null ? String(from.id) : null,
    chat_id: msg.chat.id,
    // Group name, not personal data - only present for groups/supergroups,
    // not private chats (msg.chat.title is undefined there).
    chat_title: msg.chat.title || null,
    message_id: msg.message_id
  }
};

const res = $json;
const isNew = res.status === 'saved';
const text = isNew
  ? `✅ Idea saved!\n📌 ${res.title}\n${res.summary}`
  : `ℹ️ ${res.title || 'This looks similar to an existing idea'}\n${res.summary || 'A similar idea already exists — nothing new was saved.'}`;

return { json: { reply_text: text, status: res.status, similar_found: res.similar_found } };

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { json: { status: 'error', title: '', summary: 'Could not parse the AI response - please try again.', is_blocking: false, addressed_to: null, tags: [], keywords: [], needs_clarification: false, clarifying_question: null } };
}

const structurallyValid =
  parsed &&
  typeof parsed.title === 'string' &&
  typeof parsed.summary === 'string' &&
  Array.isArray(parsed.tags) &&
  Array.isArray(parsed.keywords) &&
  typeof parsed.needs_clarification === 'boolean';

if (!structurallyValid) {
  return { json: { status: 'error', title: '', summary: 'AI response was missing required fields - please try again.', is_blocking: false, addressed_to: null, tags: [], keywords: [], needs_clarification: false, clarifying_question: null } };
}

return {
  json: {
    status: 'ok',
    title: parsed.title,
    summary: parsed.summary, is_blocking: parsed.is_blocking ?? false, addressed_to: parsed.addressed_to ?? null,
    tags: parsed.tags,
    keywords: parsed.keywords,
    needs_clarification: parsed.needs_clarification,
    clarifying_question: parsed.clarifying_question ?? null
  }
};

