const row=$json; const p=row.payload||{};
const isArabic=/[؀-ۿ]/.test(`${p.title||''} ${p.summary||''}`);
const preview_text=isArabic
? `📝 راجع قبل الحفظ

📌 ${p.title}
${p.summary}

هل تريد حفظ هذه المعرفة؟`
: `📝 Review before saving

📌 ${p.title}
${p.summary}

Do you want to save this knowledge?`;
return {json:{...row,preview_text}};

const q=$json.callback_query;
const m=String(q?.data||'').match(/^(save|cancel):(\d+)$/);
return {json:{
  valid:!!m,
  action:m?.[1]??null,
  pending_id:m?Number(m[2]):null,
  callback_query_id:q?.id??null,
  callback_user_id:q?.from?.id!=null?String(q.from.id):null,
  chat_id:q?.message?.chat?.id??null,
  message_id:q?.message?.message_id??null
}};
